from rest_framework import serializers, viewsets, permissions
from .models import Invoice


class InvoiceSerializer(serializers.ModelSerializer):
    order_number = serializers.CharField(source="order.order_number", read_only=True)

    class Meta:
        model = Invoice
        fields = ["id", "order", "order_number", "invoice_number", "subtotal", "tax_amount",
                  "discount_amount", "delivery_fee", "total_amount", "payment_status",
                  "etims_reference", "issued_at"]


class InvoiceViewSet(viewsets.ReadOnlyModelViewSet):
    """Invoices are generated by orders/payments flows (see invoices.models.generate_invoice_for_order),
    not created directly through this API."""
    serializer_class = InvoiceSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        user = self.request.user
        qs = Invoice.objects.select_related("order")
        if user.is_staff:
            return qs
        return qs.filter(order__branch_id=user.branch_id)
